    merged = [intervals[0]]
    for current_s, current_t in intervals[1:]:
        last_s, last_t = merged[-1]
        if current_s <= last_t + 1:
            merged[-1] = (last_s, max(last_t, current_t))
        else:
            merged.append((current_s, current_t))

    total_days = 0
    for start, end in merged:
        total_days += (end - start + 1)

    print(total_days)

